# the same mechanism in C: clone the directory's mount here, enter A's mount namespace, attach the clone at /tools, make it private
APP_ID=$(sudo crictl --runtime-endpoint unix:///run/bench75052934/containerd.sock --image-endpoint unix:///run/bench75052934/containerd.sock ps -q --name bench75052934-app --state running)
PID=$(sudo crictl --runtime-endpoint unix:///run/bench75052934/containerd.sock --image-endpoint unix:///run/bench75052934/containerd.sock inspect -o go-template --template '{{.info.pid}}' "$APP_ID")
cat > /tmp/bench75052934-inject.c <<'CEOF'
#define _GNU_SOURCE
#include <fcntl.h>
#include <sched.h>
#include <stdio.h>
#include <sys/mount.h>
#include <sys/stat.h>
#include <sys/syscall.h>
#include <unistd.h>

int main(int argc, char **argv) {
    char ns[64];
    int tree = syscall(428 /* open_tree */, AT_FDCWD, argv[2], 1 /* OPEN_TREE_CLONE */ | O_CLOEXEC | 0x8000 /* AT_RECURSIVE */);
    if (tree < 0) { perror("open_tree"); return 1; }
    snprintf(ns, sizeof ns, "/proc/%s/ns/mnt", argv[1]);
    int fd = open(ns, O_RDONLY);
    if (fd < 0 || setns(fd, CLONE_NEWNS) < 0) { perror("setns"); return 1; }
    mkdir(argv[3], 0755);
    if (syscall(429 /* move_mount */, tree, "", AT_FDCWD, argv[3], 4 /* MOVE_MOUNT_F_EMPTY_PATH */) < 0) { perror("move_mount"); return 1; }
    /* the clone of a shared mount is a shared peer: make it private */
    if (mount(NULL, argv[3], NULL, MS_PRIVATE, NULL) < 0) { perror("make private"); return 1; }
    return 0;
}
CEOF
gcc -O1 -o /tmp/bench75052934-inject /tmp/bench75052934-inject.c
sudo /tmp/bench75052934-inject "$PID" /var/lib/bench75052934/tools /tools
